  });
  result = executeWorkflow(singleFormWorkflow([
    { path: 'options.size', type: 'integer', default: 7 },
  ]), { options: withOwn });
  assert.equal(result.status, 'completed');
  assert.equal(result.context.input.options.size, 42);
});

